-- Тема 16: правки по отчёту Codex (13 исправлений в 9 вопросах), ключи не меняются.
-- Источник: scripts/questions/098_codex_topic16_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Может ли подписчик получать изменения не напрямую с публикующего сервера, а с его физической реплики?', 'Да, но при синхронной репликации с издателем', 'Да, но нужна синхронная физическая репликация', 'Режим синхронности здесь значения не имеет.', 'Синхронность не обязательна: логическое декодирование возможно и на асинхронной физической реплике.'),
        ('option', 'Может ли подписчик получать изменения не напрямую с публикующего сервера, а с его физической реплики?', 'Да, изменения отправляет wal_sender физической реплики', 'Да, через walsender на физической реплике', NULL, NULL),
        ('option', 'Обеспечивает ли схема мастер-мастер на логической репликации глобальные распределённые транзакции?', 'Нет, общей согласованности узлов она не даёт', 'Нет, единую фиксацию она не координирует', 'Согласованность между серверами сама по себе не обеспечивается: приложение должно избегать конфликтов, а сбои и состав узлов обрабатываются внешними средствами.', 'Двунаправленная репликация сама по себе не координирует единую транзакцию на всех узлах: приложение должно избегать конфликтов, а сбои и состав узлов обрабатываются внешними средствами.'),
        ('option', 'Обеспечивает ли схема мастер-мастер на логической репликации глобальные распределённые транзакции?', 'Да, если в подписках указать origin = none', NULL, 'Параметр лишь исключает пересылку полученных изменений обратно.', 'origin = none отбрасывает изменения, пришедшие по репликации с других узлов: это убирает циклическую пересылку, но фиксацию не координирует.'),
        ('option', 'Что дополнительно попадает в журнал при wal_level = logical?', 'Идентификаторы строк и сведения об изменении схемы', 'Идентификаторы строк и сведения о каталогах', 'Идентификаторы изменяемых строк и сведения об изменении определений таблиц и типов нужны, чтобы сформировать сообщения об изменениях на уровне строк.', 'Идентификаторы изменяемых строк и сведения из системного каталога об определениях таблиц и типов нужны, чтобы сформировать сообщения об изменениях строк. Перенос DDL они не обеспечивают: схему на подписчике поддерживают отдельно.'),
        ('option', 'Что из перечисленного не реплицируется логической репликацией?', 'Значения последовательностей', 'Последовательности (SEQUENCE)', 'Последовательности не реплицируются.', 'Состояние последовательностей не реплицируется; значения serial и identity в строках передаются вместе с таблицей.'),
        ('option', 'Что не передаётся логической репликацией?', 'Значения последовательностей', 'Последовательности (SEQUENCE)', 'Последовательности не реплицируются.', 'Состояние последовательностей не реплицируется; значения serial и identity в строках передаются вместе с таблицей.'),
        ('option', 'Что не передаётся логической репликацией?', 'Команды DDL', 'Изменения схемы (DDL)', NULL, NULL),
        ('option', 'Какая совместимость серверов нужна для логической репликации?', 'Совместимость протокола, а не двоичная', 'Протокольная, без совместимости файлов', NULL, NULL),
        ('explanation', 'Какая совместимость серверов нужна для логической репликации?', NULL, NULL, 'Поэтому логическую репликацию используют для обновления основной версии без простоя.', 'Поэтому логическую репликацию используют для обновления основной версии с минимальным перерывом на переключение.'),
        ('option', 'Чем логическая репликация отличается от физической?', 'Не нужна двоичная совместимость серверов', 'Не нужна совместимость файлов кластера', NULL, NULL),
        ('explanation', 'Почему для обновления основной версии без прерывания обслуживания не подходит физическая репликация?', NULL, NULL, 'Логическая репликация требует только совместимости на уровне протокола.', 'Логическая репликация допускает разные основные версии: нужны совместимые протокол, структура таблиц и форматы передаваемых типов.'),
        ('option', 'Что передаётся подписчику при логической репликации?', 'Сегменты WAL целиком, без декодирования', NULL, 'Файлы WAL передаёт физическая репликация.', 'Физическая репликация передаёт WAL потоком записей или файлами сегментов, а логическая — результат декодирования.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
